<!doctype html>
<html lang="{{ $locale }}" dir="{{ $locale === 'fa' ? 'rtl' : 'ltr' }}">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="color-scheme" content="dark light"><title>Hermes · ServerNet</title>
<script src="https://tapi.bale.ai/miniapp.js"></script>
<style>
:root{color-scheme:dark;--bg:#101315;--panel:#171c1f;--raised:#20272b;--ink:#eef3f2;--muted:#96a5a5;--line:#2b3539;--accent:#a8e4cc;--accentInk:#123629;--bubble:#263f38;--danger:#efbc96;--shadow:0 18px 64px #0002}
body.light{color-scheme:light;--bg:#f5f7f6;--panel:#fff;--raised:#edf2ef;--ink:#1a2d28;--muted:#63776e;--line:#dce6e0;--accent:#22785b;--accentInk:#fff;--bubble:#e2efe8;--danger:#9f5424;--shadow:0 16px 50px #173e2810}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg)}body{font:14px/1.9 Tahoma,"Segoe UI",Arial,sans-serif;color:var(--ink)}button,textarea,select{font:inherit}button,select{cursor:pointer}button{color:inherit;border:0;background:none;transition:background .15s,transform .15s}button:hover{background:var(--raised)}button:disabled{opacity:.5;cursor:wait}button:active{transform:translateY(1px)}:focus-visible{outline:2px solid var(--accent);outline-offset:4px}button,select{min-height:40px}a{color:var(--accent)}textarea{width:100%;resize:vertical;background:transparent;color:var(--ink);border:0;outline:none;line-height:1.9}textarea::placeholder{color:var(--muted)}.hidden{display:none!important}.shell{max-width:1480px;margin:auto;display:grid;grid-template-columns:246px minmax(0,1fr);min-height:100dvh}.sidebar{border-inline-end:1px solid var(--line);padding:32px 22px;display:flex;flex-direction:column;gap:28px;position:sticky;top:0;height:100dvh}.brand{display:flex;gap:12px;align-items:center}.mark{width:43px;height:43px;background:var(--accent);color:var(--accentInk);border-radius:15px;display:grid;place-items:center;font:bold 29px Georgia,serif;box-shadow:0 0 38px #a8e4cc10}.brand-name{font:bold 20px Georgia,serif;letter-spacing:1px;direction:ltr}.caption{font-size:11px;color:var(--muted)}.wordmark{font:10px Arial,sans-serif;letter-spacing:2px;direction:ltr}.nav{display:flex;flex-direction:column;gap:7px}.nav button{display:flex;align-items:center;gap:11px;padding:10px 13px;text-align:start;border-radius:12px;color:var(--muted)}.nav button.active{background:var(--raised);color:var(--accent)}.icon{width:20px;flex-shrink:0;display:inline-grid;place-items:center;font:20px Arial,sans-serif}.sidebar-foot{margin-top:auto;padding-top:20px;border-top:1px solid var(--line)}.tiny-dot{display:inline-block;width:6px;height:6px;background:var(--accent);border-radius:50%;margin-inline-end:7px}.workspace{min-width:0;display:flex;flex-direction:column;height:100dvh}.topbar{padding:22px 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:12px;flex-shrink:0}.topbar h1{font-size:15px;margin:0;font-weight:500}.tools{display:flex;align-items:center;gap:7px}.icon-button{width:40px;border:1px solid var(--line);border-radius:12px}.language{color:var(--muted);background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:0 9px;font-size:11px}.main{flex:1;min-height:0;overflow:auto;scroll-behavior:smooth}.view{max-width:850px;margin:0 auto;padding:32px 30px}.chat-view{padding-bottom:20px;min-height:100%;display:flex;flex-direction:column}.welcome{margin:auto;text-align:center;padding:48px 0 26px}.welcome .orb{width:78px;height:78px;display:grid;place-items:center;margin:0 auto 23px;border:1px solid #a8e4cc44;background:radial-gradient(ellipse at 30% 20%,#a8e4cc28,transparent 75%);border-radius:26px;color:var(--accent);font:49px Georgia,serif;transform:rotate(-6deg)}.welcome h2{font-size:27px;font-weight:500;letter-spacing:-1px;margin:0 0 14px}.welcome p{max-width:440px;margin:auto;color:var(--muted);font-size:13px}.suggestions{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:30px auto 0;max-width:530px}.suggestion{border:1px solid var(--line);border-radius:14px;text-align:start;padding:14px 16px;background:var(--panel);display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px}.suggestion span:last-child{color:var(--accent);font-size:17px}.messages{display:flex;flex-direction:column;gap:26px}.message{max-width:94%;align-self:flex-start}.message.user{align-self:flex-end;max-width:84%}.message-head{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:10px;margin-bottom:7px}.user .message-head{justify-content:flex-end}.message-text{white-space:pre-wrap;overflow-wrap:anywhere;unicode-bidi:plaintext;line-height:2;font-size:13px}.user .message-text{background:var(--bubble);border:1px solid var(--line);border-radius:18px 18px 4px 18px;padding:13px 18px}.assistant .message-text{padding:3px 0}.message-actions{display:flex;gap:10px;margin-top:7px}.message-actions button{font-size:10px;color:var(--muted);min-height:30px;padding:2px 7px}.delivery{font-size:10px;color:var(--danger);margin-top:7px;max-width:520px}.composer-area{padding:10px 30px 18px;flex-shrink:0;background:var(--bg)}.composer{max-width:790px;margin:auto;background:var(--panel);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);padding:15px 16px 10px}.composer:focus-within{border-color:var(--accent)}.composer textarea{resize:none;min-height:52px;max-height:180px;font-size:13px}.composer-bottom{display:flex;align-items:center;justify-content:space-between;gap:8px}.composer-memory{font-size:10px;color:var(--muted);padding:4px 7px;border-radius:8px}.send{background:var(--accent);color:var(--accentInk);height:40px;padding:6px 18px;border-radius:12px;font-size:12px;font-weight:bold}.send:hover{filter:brightness(.92);background:var(--accent)}.composer-note{text-align:center;color:var(--muted);font-size:9px;margin:7px 0 0}.typing{padding:6px 1px;color:var(--accent);font-size:11px;display:flex;align-items:center;gap:8px}.pulse{width:5px;height:5px;border-radius:50%;background:var(--accent);animation:pulse 1s infinite alternate}.notice{margin:12px 30px 0;background:var(--panel);border:1px solid #b08c6444;border-radius:12px;padding:12px 15px;font-size:12px;color:var(--danger);display:flex;align-items:center;justify-content:space-between;gap:12px;flex-shrink:0}.notice button{font-size:11px;text-decoration:underline;white-space:nowrap}.gate{margin:auto;padding:60px 30px;text-align:center;max-width:500px}.gate h2{font-size:20px}.gate p{color:var(--muted);font-size:12px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:3px 0 25px}.section-head h2{font-size:21px;margin:0}.section-head p{color:var(--muted);font-size:12px;margin:5px 0 0}.subtle-button{background:var(--raised);border-radius:10px;padding:5px 13px;font-size:11px}.memory-editor{border:1px solid var(--line);border-radius:18px;background:var(--panel);padding:18px}.memory-editor textarea{min-height:80px;font-size:13px}.memory-meta{display:flex;justify-content:space-between;align-items:center;gap:12px;color:var(--muted);font-size:10px}.memory-list{display:flex;flex-direction:column;gap:12px;margin-top:24px}.memory-card{padding:18px;border:1px solid var(--line);border-radius:16px;background:var(--panel)}.memory-card p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.memory-card .row{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:12px}.memory-card button{font-size:11px;color:var(--muted);min-height:32px;padding:3px 8px}.memory-card button:last-child{color:var(--danger)}.note{color:var(--muted);font-size:11px;margin:17px 0;line-height:1.9}.empty{text-align:center;color:var(--muted);padding:32px 10px;font-size:12px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metric{border:1px solid var(--line);border-radius:17px;padding:19px;background:var(--panel)}.metric strong{display:block;font:32px Arial,sans-serif;margin-top:15px}.metric span{font-size:11px;color:var(--muted)}.services{display:grid;grid-template-columns:repeat(2,1fr);gap:11px;margin:25px 0 0}.service{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:15px;display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.badge{font-size:10px;color:var(--muted)}.badge.good{color:var(--accent)}.badge.warn{color:var(--danger)}.mobile-brand{display:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@keyframes pulse{to{opacity:.25}}@media(max-width:900px){.shell{grid-template-columns:200px 1fr}.sidebar{padding:25px 16px}.topbar{padding:20px 24px}.view{padding:28px 24px}.composer-area{padding:10px 24px 14px}.welcome h2{font-size:24px}}@media(max-width:640px){.shell{display:block}.sidebar{position:fixed;z-index:5;bottom:0;top:auto;height:auto;width:100%;border:0;border-top:1px solid var(--line);background:var(--panel);padding:5px 14px max(5px,env(safe-area-inset-bottom));display:block}.sidebar .brand,.sidebar-foot,.sidebar>.caption{display:none}.nav{flex-direction:row;justify-content:space-around;gap:3px}.nav button{flex-direction:column;gap:0;padding:5px 20px;font-size:10px;flex:1;min-height:48px}.nav .icon{font-size:17px;height:22px}.workspace{height:calc(100dvh - 69px - env(safe-area-inset-bottom))}.topbar{padding:13px 18px}.topbar h1{font-size:12px}.mobile-brand{display:block;font:20px Georgia,serif;color:var(--accent)}.topbar .caption{font-size:9px}.tools{gap:5px}.language{max-width:62px;padding:0 4px}.view{padding:24px 18px}.welcome{padding:26px 0 20px}.welcome h2{font-size:21px}.welcome p{font-size:12px;max-width:320px}.welcome .orb{width:64px;height:64px;font-size:40px;border-radius:22px;margin-bottom:20px}.suggestions{margin-top:24px;gap:8px}.suggestion{font-size:10px;padding:12px 11px;border-radius:12px}.composer-area{padding:7px 14px 9px}.composer{padding:12px 12px 9px;border-radius:17px}.composer-note{display:none}.composer textarea{min-height:44px}.notice{margin:8px 14px 0;font-size:11px;padding:10px 12px}.metrics{gap:8px}.metric{padding:14px 10px}.metric strong{font-size:26px}.metric span{font-size:9px}.services{grid-template-columns:1fr}.section-head h2{font-size:19px}.message{max-width:100%}.message.user{max-width:90%}.message-text{font-size:12px}.message.user .message-text{padding:10px 14px}.section-head{gap:10px}.section-head p{font-size:11px}.memory-meta{align-items:flex-start;flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important;transition:none!important}}
</style>
</head>
<body><div class="shell">
<aside class="sidebar"><div class="brand"><div class="mark" aria-hidden="true">h</div><div><div class="brand-name">Hermes</div><div class="wordmark">BY SERVERNET</div></div></div><div class="caption" data-i18n="private"></div><nav class="nav" aria-label="Hermes"><button class="active" data-view="chat" aria-current="page"><span class="icon" aria-hidden="true">◇</span><span data-i18n="chat"></span></button><button data-view="memory"><span class="icon" aria-hidden="true">✧</span><span data-i18n="memory"></span></button><button data-view="status"><span class="icon" aria-hidden="true">▤</span><span data-i18n="status"></span></button></nav><div class="sidebar-foot"><span class="tiny-dot"></span><span class="caption" data-i18n="private"></span><div class="wordmark" style="margin-top:12px;color:var(--muted)">SERVERNET · HERMES</div></div></aside>
<div class="workspace"><header class="topbar"><div><div class="mobile-brand">Hermes</div><h1 data-i18n="title"></h1><div class="caption" id="connection" role="status"></div></div><div class="tools"><select id="language" class="language" aria-label="Language"><option value="fa">فارسی</option><option value="en">EN</option><option value="tr">TR</option></select><button id="theme" class="icon-button" aria-label="Theme">◐</button><button id="clear" class="icon-button" aria-label="Clear history">↺</button></div></header>
<div id="notice" class="notice hidden" role="alert"><span id="noticeText"></span><button id="retry" data-i18n="retry"></button></div>
<section id="gate" class="gate"><div class="mark" style="margin:auto" aria-hidden="true">h</div><h2 id="gateTitle"></h2><p id="gateText"></p></section>
<main id="main" class="main hidden"><section id="view-chat" class="view chat-view"><div id="welcome" class="welcome"><div class="orb" aria-hidden="true">h</div><h2 data-i18n="welcome"></h2><p data-i18n="intro"></p><div class="suggestions"><button class="suggestion" data-prompt="servers_prompt"><span data-i18n="servers_label"></span><span aria-hidden="true">↗</span></button><button class="suggestion" data-prompt="develop_prompt"><span data-i18n="develop_label"></span><span aria-hidden="true">↗</span></button><button class="suggestion" data-prompt="network_prompt"><span data-i18n="network_label"></span><span aria-hidden="true">↗</span></button><button class="suggestion" id="learn"><span data-i18n="learn_label"></span><span aria-hidden="true">＋</span></button></div></div><div id="messages" class="messages" role="log" aria-live="polite"></div><div id="typing" class="typing hidden" role="status"><span class="pulse"></span><span data-i18n="thinking"></span></div></section>
<section id="view-memory" class="view hidden"><div class="section-head"><div><h2 data-i18n="memory"></h2><p data-i18n="memory_hint"></p></div><span id="memoryCount" class="caption"></span></div><form id="memoryForm" class="memory-editor"><label for="memoryText" class="sr-only" data-i18n="memory"></label><textarea id="memoryText" maxlength="500"></textarea><div class="memory-meta"><span id="memoryLength">0 / 500</span><div><button type="button" id="cancelMemory" class="hidden" data-i18n="cancel"></button><button id="saveMemory" class="send" data-i18n="save"></button></div></div></form><p class="note" data-i18n="memory_learn"></p><div id="memoryList" class="memory-list"></div><p class="note" data-i18n="memory_note"></p><p class="note" data-i18n="memory_limit"></p></section>
<section id="view-status" class="view hidden"><div class="section-head"><div><h2 data-i18n="status"></h2><p id="updated">—</p></div><button id="refresh" class="subtle-button" data-i18n="refresh"></button></div><div class="metrics"><div class="metric"><span data-i18n="running"></span><strong id="running">—</strong></div><div class="metric"><span data-i18n="stopped"></span><strong id="stopped">—</strong></div><div class="metric"><span data-i18n="containers"></span><strong id="containers">—</strong></div></div><div id="services" class="services"></div><p class="note" data-i18n="infra_note"></p></section></main>
<div id="composerArea" class="composer-area hidden"><form id="chatForm" class="composer"><label for="message" class="sr-only" data-i18n="placeholder"></label><textarea id="message" maxlength="4000" rows="2"></textarea><div class="composer-bottom"><button id="showMemory" type="button" class="composer-memory">✧ <span data-i18n="memory"></span> <span id="composerMemoryCount"></span></button><button id="send" class="send" data-i18n="send"></button></div></form><p class="composer-note" data-i18n="hint"></p></div>
</div></div>
<dialog id="confirmDialog" style="background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:18px;padding:24px;max-width:calc(100% - 32px);width:360px"><p id="confirmText"></p><div style="display:flex;gap:12px;margin-top:20px"><button id="confirmYes" class="send" data-i18n="confirm"></button><button id="confirmNo" class="subtle-button" data-i18n="cancel"></button></div></dialog>
<script>
(()=>{
'use strict';
const L=@json($labels),lang=@json($locale),$=id=>document.getElementById(id),app=window.Bale&&window.Bale.WebApp;
let session=null,authorized=false,busy=false,currentView='chat',state={messages:[],memories:[]},editing=null,overviewLoaded=false,pollTimer=null,syncing=false;
const number=n=>new Intl.NumberFormat(lang==='fa'?'fa-IR':lang).format(n),t=k=>L[k]||L.unknown;
document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));
$('message').placeholder=t('placeholder');$('memoryText').placeholder=t('memory_placeholder');$('theme').setAttribute('aria-label',t('theme'));$('clear').setAttribute('aria-label',t('new_chat'));$('language').value=lang;
$('connection').textContent=t('connecting');$('gateTitle').textContent=t('connecting');$('gateText').textContent=t('private');
const dark=app?.colorScheme==='dark'||window.matchMedia('(prefers-color-scheme: dark)').matches;document.body.classList.toggle('light',!dark);
$('theme').onclick=()=>document.body.classList.toggle('light');$('language').onchange=()=>{const u=new URL(location.href);u.searchParams.set('lang',$('language').value);location.assign(u.toString())};
function notice(code){$('noticeText').textContent=code?t(code):'';$('notice').classList.toggle('hidden',!code)}
function fail(code){notice(code||'unknown')}
function confirmAction(text){return new Promise(resolve=>{const d=$('confirmDialog');$('confirmText').textContent=text;const done=value=>{d.close();resolve(value)};$('confirmYes').onclick=()=>done(true);$('confirmNo').onclick=()=>done(false);d.oncancel=e=>{e.preventDefault();done(false)};d.showModal()})}
function show(view){currentView=view;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});['chat','memory','status'].forEach(v=>$('view-'+v).classList.toggle('hidden',v!==view));$('composerArea').classList.toggle('hidden',!authorized||view!=='chat');if(view==='status'&&!overviewLoaded)overview()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));$('showMemory').onclick=$('learn').onclick=()=>{show('memory');$('memoryText').focus()};
function headers(){const h={'Accept':'application/json'};if(session&&session.expires_at*1000>Date.now())h['X-Hermes-Session']=session.token;else if(app?.initData)h['X-Bale-Init-Data']=app.initData;return h}
async function api(path,body,timeout=30000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const res=await fetch('/bale/hermes/'+path,{method:body===undefined?'GET':'POST',credentials:'omit',headers:{...headers(),...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',redirect:'error',signal:controller.signal});const type=res.headers.get('content-type')||'';if(!type.includes('application/json'))throw {code:'service_unavailable'};const data=await res.json();if(res.status===401||res.status===403){authorized=false;session=null;try{sessionStorage.removeItem('hermes-miniapp-session')}catch{};$('connection').textContent=t('session_expired');$('send').disabled=true;throw {code:'session_expired'}}if(!res.ok||data.ok===false)throw {code:res.status===429?'rate_limited':data.code||'unknown'};return data}catch(e){throw {code:e.code||'connection_error'}}finally{clearTimeout(timer)}}
function date(at){return new Date(at*1000).toLocaleTimeString(lang==='fa'?'fa-IR':lang,{hour:'2-digit',minute:'2-digit'})}
function scroll(){requestAnimationFrame(()=>$('main').scrollTo({top:$('main').scrollHeight,behavior:'smooth'}))}
function render(){const list=$('messages');list.replaceChildren();$('welcome').classList.toggle('hidden',state.messages.length>0);for(const m of state.messages){const box=document.createElement('article'),head=document.createElement('div'),text=document.createElement('div');box.className='message '+(m.role==='user'?'user':'assistant');head.className='message-head';head.textContent=(m.role==='user'?t('you'):t('assistant'))+' · '+date(m.at);text.className='message-text';text.dir='auto';text.textContent=m.text;box.append(head,text);if(m.status==='pending'||m.status==='uncertain'){const s=document.createElement('div');s.className='delivery';s.textContent=m.status==='pending'&&Date.now()/1000-m.at<600?t('thinking'):t('uncertain');box.append(s)}if(m.role==='assistant'){const row=document.createElement('div'),copy=document.createElement('button');row.className='message-actions';copy.textContent=t('copy');copy.onclick=async()=>{try{await navigator.clipboard.writeText(m.text);copy.textContent=t('copied')}catch{copy.textContent=t('copy')}};row.append(copy);box.append(row)}list.append(box)}$('memoryCount').textContent=number(state.memories.length)+' '+t('memory_count');$('composerMemoryCount').textContent=number(state.memories.length);$('memoryList').replaceChildren();if(!state.memories.length){const e=document.createElement('div');e.className='empty';e.textContent=t('memory_empty');$('memoryList').append(e)}for(const m of state.memories){const card=document.createElement('article'),p=document.createElement('p'),row=document.createElement('div'),time=document.createElement('span'),actions=document.createElement('div'),edit=document.createElement('button'),del=document.createElement('button');card.className='memory-card';p.dir='auto';p.textContent=m.text;row.className='row';time.className='caption';time.textContent=new Date(m.updated_at*1000).toLocaleDateString(lang==='fa'?'fa-IR':lang);edit.textContent=t('edit');edit.onclick=()=>{editing=m.id;$('memoryText').value=m.text;$('memoryText').focus();$('cancelMemory').classList.remove('hidden');$('memoryText').dispatchEvent(new Event('input'))};del.textContent=t('delete');del.onclick=async()=>{if(!await confirmAction(t('delete_confirm')))return;del.disabled=true;try{const d=await api('memory',{action:'delete',id:m.id});state=d.state;render()}catch(e){fail(e.code)}finally{del.disabled=false}};actions.append(edit,del);row.append(time,actions);card.append(p,row);$('memoryList').append(card)}}
function pending(on){busy=on;$('send').disabled=on||!authorized;$('clear').disabled=on;$('typing').classList.toggle('hidden',!on);$('connection').textContent=t(on?'thinking':'online');$('message').setAttribute('aria-busy',String(on))}
async function start(){if(!app?.initData){$('gateTitle').textContent=t('open_bale');$('gateText').textContent=t('open_hint');$('connection').textContent=t('private');return}try{notice('');const launch=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(app.initData)))).map(x=>x.toString(16).padStart(2,'0')).join('');try{const saved=JSON.parse(sessionStorage.getItem('hermes-miniapp-session'));if(saved?.launch===launch&&saved.session?.expires_at*1000>Date.now())session=saved.session}catch{}const d=await api('session');if(d.session){session=d.session;try{sessionStorage.setItem('hermes-miniapp-session',JSON.stringify({launch,session}))}catch{}}state=d.state;authorized=true;$('gate').classList.add('hidden');$('main').classList.remove('hidden');$('connection').textContent=t('online');$('send').disabled=false;render();show(currentView);schedulePoll()}catch(e){$('gateTitle').textContent=t('open_bale');$('gateText').textContent=t(e.code);fail(e.code)}}
function schedulePoll(){clearTimeout(pollTimer);const waiting=state.messages.some(m=>['pending','uncertain'].includes(m.status)&&Date.now()/1000-m.at<600);pending(waiting);if(waiting&&authorized)pollTimer=setTimeout(sync,3000)}
async function sync(){if(syncing)return;if(!authorized){await start();return}syncing=true;try{const d=await api('state');state=d.state;render();notice('')}catch(e){fail(e.code)}finally{syncing=false;schedulePoll()}}
$('retry').onclick=sync;
$('chatForm').onsubmit=async e=>{e.preventDefault();if(busy||!authorized)return;const text=$('message').value.trim();if(!text)return;const learn=text.match(/^(?:یاد بگیر|به خاطر بسپار|remember|learn|hatırla)\s*[:：]\s*([\s\S]+)$/iu);if(learn){if(Array.from(learn[1]).length>500){show('memory');$('memoryText').value=learn[1];$('memoryText').dispatchEvent(new Event('input'));$('memoryText').focus();fail('memory_limit');return}pending(true);try{const d=await api('memory',{action:'save',text:learn[1]});state=d.state;$('message').value='';render();show('memory');notice('memory_saved')}catch(e){fail(e.code)}finally{pending(false)}return}const id=crypto.randomUUID();pending(true);notice('');$('message').value='';state.messages.push({id,role:'user',text,at:Date.now()/1000,status:'pending'});render();scroll();try{const d=await api('chat',{id,text},25000);state=d.state;render();if(d.delivery==='uncertain')fail('uncertain')}catch(e){const m=state.messages.find(m=>m.id===id);if(m)m.status='uncertain';render();fail(e.code)}finally{schedulePoll();scroll()}};
$('message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('chatForm').requestSubmit()}};
document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('message').value=t(b.dataset.prompt);$('message').focus()});
$('clear').onclick=async()=>{if(!authorized||busy||!await confirmAction(t('clear_confirm')))return;try{const d=await api('history/clear',{});state=d.state;render();notice('')}catch(e){fail(e.code)}};
$('memoryText').oninput=()=>$('memoryLength').textContent=number(Array.from($('memoryText').value).length)+' / 500';
function resetMemory(){editing=null;$('memoryText').value='';$('memoryText').dispatchEvent(new Event('input'));$('cancelMemory').classList.add('hidden')}
$('cancelMemory').onclick=resetMemory;
$('memoryForm').onsubmit=async e=>{e.preventDefault();if(!authorized)return;const text=$('memoryText').value.trim();if(!text)return;$('saveMemory').disabled=true;try{const d=await api('memory',{action:'save',id:editing,text});state=d.state;resetMemory();render();notice('memory_saved')}catch(e){fail(e.code)}finally{$('saveMemory').disabled=false}};
async function overview(){if(!authorized)return;$('refresh').disabled=true;try{const d=await api('overview',undefined,45000);$('running').textContent=d.summary?.qemu?.running==null?'—':number(d.summary.qemu.running);$('stopped').textContent=d.summary?.qemu?.stopped==null?'—':number(d.summary.qemu.stopped);$('containers').textContent=d.summary?.lxc?.running==null?'—':number(d.summary.lxc.running);$('updated').textContent=t('updated')+': '+date(d.utc||Date.now()/1000);$('services').replaceChildren();const names={'proxmox-ir':'Proxmox · IR','proxmox-ir-shell':'Host management','whm-ir':'WHM · IR','whm-de':'WHM · DE','n8n-ir':'n8n','plesk-ir':'Plesk · Windows'};for(const[k,v]of Object.entries(d.integrations||{})){const row=document.createElement('div'),name=document.createElement('span'),badge=document.createElement('span');row.className='service';name.textContent=names[k]||k;name.dir='ltr';badge.className='badge'+(v.connected===true?' good':v.connected===false?' warn':'');badge.textContent=t(v.connected===true?'verified':v.connected===false?(v.configured?'not_verified':'needs_setup'):v.configured?'configured':'needs_setup');row.append(name,badge);$('services').append(row)}overviewLoaded=true;notice(d.overview_available===false?'service_unavailable':'')}catch(e){fail(e.code)}finally{$('refresh').disabled=false}}
$('refresh').onclick=overview;
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&authorized)sync()});
if(app?.ready)app.ready();start();
})();
</script></body></html>
